-- Lets Admins upload, replace and remove staff photos in the public `sales-avatar` bucket.
-- Add-only: creates four storage policies, changes no table, touches no existing file.
-- DO NOT EDIT THIS FILE ONCE IT HAS BEEN APPLIED TO ANY DATABASE. Later changes go in a new file.
--
-- The bucket is public, so anyone with a photo's link can view it; these policies only
-- control who may write. New photos are stored at `<sales_users.id>/<file name>`.
-- The one existing photo (`rist.jpeg`, at the bucket root) keeps working unchanged.

create policy sales_avatar_admin_select on storage.objects
    for select to authenticated
    using (bucket_id = 'sales-avatar' and (select public.is_admin()));

create policy sales_avatar_admin_insert on storage.objects
    for insert to authenticated
    with check (bucket_id = 'sales-avatar' and (select public.is_admin()));

create policy sales_avatar_admin_update on storage.objects
    for update to authenticated
    using (bucket_id = 'sales-avatar' and (select public.is_admin()))
    with check (bucket_id = 'sales-avatar' and (select public.is_admin()));

create policy sales_avatar_admin_delete on storage.objects
    for delete to authenticated
    using (bucket_id = 'sales-avatar' and (select public.is_admin()));
